<?php
declare(strict_types=1);
function visibility_folder_path(mixed $value): string {if(!is_string($value))fail('validation','Choose a folder path.');$path=trim(str_replace('\\','/',$value),'/');if(!$path||strlen($path)>2000||preg_match('~(?:^|/)(?:\.|\.\.)(?:/|$)|//|[\x00-\x1f]~',$path))fail('validation','Choose a valid folder path.');return $path;}
function visibility_rows(PDO $db,string $table,array $ids,string $column='id',string $select='*'): array {$rows=[];foreach(array_chunk($ids,200)as $group)$rows=array_merge($rows,query_all($db,'SELECT '.$select.' FROM '.$table.' WHERE deleted=0 AND '.$column.' IN('.implode(',',array_fill(0,count($group),'?')).') LIMIT 10001',$group));return $rows;}
function visibility_routes(PDO $db,array $auth,string $path,string $method): bool {
 if($path!=='/api/visibility'||$method!=='POST')return false;$input=metadata_object(metadata_json_body(),'Request');if(!array_key_exists('alsoMyTracks',$input)&&array_key_exists('applyToTracks',$input))$input['alsoMyTracks']=$input['applyToTracks'];$targets=$input['targets']??null;if(!is_array($targets)||!count($targets)||count($targets)>2000)fail('validation','Choose 1–2000 visibility targets.');$ids=['track'=>[],'album'=>[],'playlist'=>[]];$paths=[];foreach($targets as $raw){$target=metadata_object($raw,'Visibility target');$type=$target['type']??'';if($type==='folder'){$paths[visibility_folder_path($target['path']??null)]=true;continue;}if(!isset($ids[$type]))fail('validation','Choose tracks, albums, playlists or folders.');$ids[$type][journal_ids([$target['id']??null])[0]]=true;}
 $visibility=$input['visibility']??null;if(!in_array($visibility,['private','public'],true))fail('validation','Choose Private or Public.');foreach(['dryRun','syncFuture','alsoMyTracks']as $flag)if(array_key_exists($flag,$input)&&!is_bool($input[$flag]))fail('validation',$flag.' must be true or false.');$uid=$auth['user']['id'];$also=$input['alsoMyTracks']??($visibility==='public');if($auth['user']['role']==='listener'&&($ids['track']||$ids['album']||$paths))fail('forbidden','Your account can change only its own playlists.',403);
 $repo=new MetadataRepositoryNative($db);$direct=$repo->tracks(array_keys($ids['track']));$albums=$repo->albums(array_keys($ids['album']));$playlists=visibility_rows($db,'playlists',array_keys($ids['playlist']));if(count($direct)!==count($ids['track'])||count($albums)!==count($ids['album'])||count($playlists)!==count($ids['playlist']))fail('not_found','A selected item was not found.',404);foreach($playlists as $row)if($row['owner_id']!==$uid)fail('forbidden','Only the playlist owner can change its visibility.',403);
 $columns='id,rev,owner_id,album_id,artist_id,visibility,deleted,original_path';$children=visibility_rows($db,'tracks',array_keys($ids['album']),'album_id',$columns);$items=visibility_rows($db,'playlist_items',array_keys($ids['playlist']));$playlistTracks=visibility_rows($db,'tracks',array_values(array_unique(array_column($items,'track_id'))),'id',$columns);$playlistTracks=array_values(array_filter($playlistTracks,fn($row)=>$row['owner_id']===$uid||$row['visibility']==='public'));$ownPlaylistTracks=array_values(array_filter($playlistTracks,fn($row)=>$row['owner_id']===$uid));$skipped=count($playlistTracks)-count($ownPlaylistTracks);$folderTracks=[];$rules=[];
 foreach(array_keys($paths)as $folder){foreach(query_all($db,'SELECT '.$columns.' FROM tracks WHERE deleted=0 AND owner_id=? AND substr(original_path,1,length(?))=? LIMIT 10001',[$uid,$folder.'/',$folder.'/'])as $row)$folderTracks[$row['id']]=$row;$rule=query_one($db,'SELECT * FROM folder_rules WHERE owner_id=? AND path=?',[$uid,$folder]);if($rule)$rules[$folder]=$rule;}
 $tracks=array_values(array_column([...$direct,...$children,...array_values($folderTracks),...($also?$ownPlaylistTracks:[])],null,'id'));$all=[...$tracks,...$albums,...$playlists,...array_values($rules)];if(count($all)+count($items)>10000)fail('too_large','Choose fewer visibility targets.',413);if($tracks&&$auth['user']['role']==='listener')fail('forbidden','Your account cannot publish tracks.',403);foreach([...$tracks,...$albums]as $row)if($row['owner_id']!==$uid&&(!in_array($auth['user']['role'],['owner','admin'],true)||$visibility==='public'))fail('forbidden','Only the uploader can publish music. Admins can make it private.',403);
 $revisions=[];foreach($all as $row)$revisions[$row['id']]=(int)$row['rev'];if(array_key_exists('expectedRevs',$input))foreach(metadata_object($input['expectedRevs'],'Expected revisions')as $id=>$rev){if(!array_key_exists($id,$revisions)||(!is_int($rev)&&!is_float($rev))||floor((float)$rev)!==(float)$rev||$rev<0||$rev>9007199254740991)fail('validation','Expected revisions must belong to these targets.');if($revisions[$id]!== (int)$rev)journal_conflict();}
 $ops=[];$guards=[];$counts=[];$updated=['tracks'=>0,'albums'=>0,'playlists'=>0];foreach(['tracks'=>$tracks,'albums'=>$albums,'playlists'=>$playlists]as $table=>$rows)foreach($rows as $row){$guards[]=['table'=>$table,'id'=>$row['id'],'rev'=>$row['rev']];$after=[...$row,'visibility'=>$visibility];if($table!=='tracks'&&array_key_exists('syncFuture',$input))$after['sync_visibility']=$input['syncFuture']?1:0;$op=journal_op($table,$row,$after);if($op){$ops[]=$op;$updated[$table]++;}}
 foreach($albums as $row)$counts[]=['table'=>'tracks','column'=>'album_id','id'=>$row['id'],'count'=>count(array_filter($children,fn($track)=>$track['album_id']===$row['id']))];foreach($playlists as $row)$counts[]=['table'=>'playlist_items','column'=>'playlist_id','id'=>$row['id'],'count'=>count(array_filter($items,fn($item)=>$item['playlist_id']===$row['id']))];
 foreach(array_keys($paths)as $folder){$before=$rules[$folder]??null;$after=['id'=>$before['id']??ulid(),'rev'=>$before['rev']??0,'owner_id'=>$uid,'path'=>$folder,'visibility'=>$visibility,'sync_visibility'=>array_key_exists('syncFuture',$input)?($input['syncFuture']?1:0):($before['sync_visibility']??1),'created_at'=>$before['created_at']??now_ms(),'deleted'=>0];$op=journal_op('folder_rules',$before,$after);if($op)$ops[]=$op;if($before)$guards[]=['table'=>'folder_rules','id'=>$before['id'],'rev'=>$before['rev']];$counts[]=['table'=>'tracks','column'=>'original_path','id'=>$folder.'/','ownerId'=>$uid,'prefix'=>true,'count'=>count(array_filter($folderTracks,fn($row)=>str_starts_with($row['original_path']??'',$folder.'/')))];}
 $publicPlaylists=[];$publicAlbums=[];if($visibility==='private')foreach(array_chunk(array_column($tracks,'id'),200)as $group){$marks=implode(',',array_fill(0,count($group),'?'));foreach(query_all($db,"SELECT DISTINCT i.playlist_id AS id FROM playlist_items i JOIN playlists p ON p.id=i.playlist_id WHERE i.deleted=0 AND p.deleted=0 AND p.visibility='public' AND i.track_id IN(".$marks.')',$group)as $row)$publicPlaylists[$row['id']]=true;foreach(query_all($db,"SELECT DISTINCT a.id FROM albums a JOIN tracks t ON t.album_id=a.id WHERE a.deleted=0 AND a.visibility='public' AND t.id IN(".$marks.')',$group)as $row)$publicAlbums[$row['id']]=true;}
 $impact=['tracksUpdated'=>$updated['tracks'],'albumsUpdated'=>$updated['albums'],'playlistsUpdated'=>$updated['playlists'],'skippedNotOwned'=>$skipped,'ownPlaylistTracks'=>count($ownPlaylistTracks),'matchedTracks'=>count($tracks),'alsoIn'=>['publicPlaylists'=>count($publicPlaylists),'publicAlbums'=>count($publicAlbums)],'revisions'=>(object)$revisions];if($input['dryRun']??false)reply([...$impact,'dryRun'=>true,'changeId'=>null]);$takedown=count(array_filter($tracks,fn($row)=>$row['owner_id']!==$uid));reply([...$impact,...journal_write($db,$auth,['undoable'=>!$takedown,'summary'=>($takedown?'Admin takedown: ':'').'Made '.count($tracks).' tracks and '.count($playlists).' playlists '.$visibility,'ops'=>$ops,'guards'=>$guards,'counts'=>$counts])]);
}
